 "content": "def transform(grid):
    """Extend a single uninterrupted marker bar through its right-side background tail."""
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda color: sum(row.count(color) for row in grid))
    marker = next((v for row in grid for v in row if v != bg), None)
    if marker is None:
        return out
