        positions = [c for c, value in enumerate(row) if value == marker]
        if not positions:
            continue
        # Only rows forming one uninterrupted marker run are extended;
        # patterned rows with internal background gaps remain unchanged.
        if positions != list(range(positions[0], positions[-1] + 1)):
            continue
        last = positions[-1]
        if all(value == bg for value in row[last + 1:]):
            for c in range(last + 1, len(row)):
                out[r][c] = 1
    return out

